// One-off codemod: rename PillComponent input `disableTooltip` -> `hideHint`.
// Usage: node rename-codemod.mjs [--apply]
import fs from "node:fs";
import path from "node:path";
import ts from "typescript";
import * as ng from "@angular/compiler";

const OLD = "disableTooltip";
const NEW = "hideHint";
const APPLY = process.argv.includes("--apply");
const root = process.cwd();
const srcDir = path.join(root, "src");

/** @type {Map<string, {start:number,end:number,why:string}[]>} */
const edits = new Map();
const notes = [];
function addEdit(file, start, end, why) {
    const abs = path.resolve(file);
    if (!edits.has(abs)) edits.set(abs, []);
    edits.get(abs).push({ start, end, why });
}
function lineOf(text, pos) { return text.slice(0, pos).split("\n").length; }

// ---------------------------------------------------------------- TypeScript
const configPath = path.join(root, "tsconfig.json");
const cfg = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(cfg.config, ts.sys, root);
